contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amount to cash out as input and also a prior depositAmount to ensure there may be balance.
    // The test will first (optionally) deposit depositAmount into c from this contract, then try CashOut(_am).
    // We observe balances before and after and whether the call reverted, and assert the general invariant.

    function run(uint depositAmount, uint _am) public payable {
        // require enough balance in this test contract to perform the deposit if requested
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "not enough ether to deposit");
            // call Deposit on c, sending depositAmount
            c.Deposit{value: depositAmount}();
        }

        // Read observable balances before CashOut
        uint before_user_bal = c.balances(address(this));
        uint before_contract_bal = address(c).balance;

        // Try CashOut and record whether it reverted
        bool reverted;
        try c.CashOut{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after_user_bal = c.balances(address(this));
        uint after_contract_bal = address(c).balance;

        // If the call reverted, both observed balances must be unchanged.
        // If it did not revert, the user's recorded balance must have decreased by _am
        // and the contract's balance must also have decreased by _am.
        // Note: use >= checks to avoid underflow in expressions inside the assert.
        assert(
            (reverted && after_user_bal == before_user_bal && after_contract_bal == before_contract_bal)
            ||
            (!reverted && before_user_bal >= _am && after_user_bal + _am == before_user_bal && before_contract_bal >= _am && after_contract_bal + _am == before_contract_bal)
        );
    }

    // Allow this test contract to receive Ether when c sends funds to it during CashOut
    receive() external payable {}
}

