contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: amount is Ether sent to c via Deposit
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // observe before-values
        uint beforeBalancePublic = c.balances(address(this));
        uint beforeCbalance = address(c).balance;

        bool reverted = false;
        // call Deposit with Ether amount
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint afterBalancePublic = c.balances(address(this));
        uint afterCbalance = address(c).balance;

        // General rule:
        // - Deposit function never reverts (Deposit uses if(msg.value > MinDeposit) and otherwise does nothing),
        //   but we still allow for external failure; however the intended invariant is:
        // - If amount > MinDeposit then the public balances[address(this)] increases by amount and contract balance increases by amount.
        // - If amount <= MinDeposit then neither balances[address(this)] nor contract balance change.
        uint minDeposit = c.MinDeposit();

        assert(
            // if deposit path taken (amount > MinDeposit)
            ((amount > minDeposit) && !reverted && afterBalancePublic == beforeBalancePublic + amount && afterCbalance == beforeCbalance + amount)
            ||
            // otherwise (amount <= MinDeposit) nothing changed (and no successful state change should have occurred)
            ((amount <= minDeposit) && afterBalancePublic == beforeBalancePublic && afterCbalance == beforeCbalance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: initial deposit amount to perform (so the test can withdraw), and withdraw amount
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");

        // ensure we start with zero recorded balance for this contract by not depending on prior state
        // perform a Deposit if depositAmount > MinDeposit to get funds into c and into c.balances(this)
        bool depReverted = false;
        uint beforePublic = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // attempt Deposit with depositAmount (may be skipped inside C if <= MinDeposit)
        try c.Deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        uint midPublic = c.balances(address(this));
        uint midCbal = address(c).balance;

        // Now attempt CashOut of withdrawAmount and record whether it reverted
        bool coReverted;
        try c.CashOut(withdrawAmount) {
            coReverted = false;
        } catch {
            coReverted = true;
        }

        uint afterPublic = c.balances(address(this));
        uint afterCbal = address(c).balance;

        // General rule to assert for all inputs:
        // 1) CashOut never increases the contract's balance: afterCbal <= midCbal.
        // 2) If CashOut succeeded (did not revert) then the public recorded balance decreased by exactly withdrawAmount
        //    (i.e. afterPublic + withdrawAmount == midPublic). We avoid underflow in the assert by requiring the equality form.
        // Note: we allow CashOut to be a no-op (if _am > balances) or to revert due to send failure; only when it succeeded we demand the recorded decrease.

        assert(
            // contract balance does not increase after CashOut
            (afterCbal <= midCbal)
            &&
            // if CashOut succeeded then recorded public balance decreased exactly by withdrawAmount
            (coReverted || (afterPublic + withdrawAmount == midPublic))
        );
    }

    // receive to accept refunds when test receives Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // depositAmount: amount to deposit into c (so recorded balance may increase)
    // withdrawAmount: amount to attempt to withdraw via CashOut
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // ensure the test contract has enough Ether to perform the deposit if desired
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");

        // Read public before-values
        uint beforeRecorded = c.balances(address(this));
        uint beforeCbal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // Attempt Deposit (may be skipped by C if depositAmount <= MinDeposit)
        bool depReverted;
        try c.Deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Read mid-state after Deposit
        uint midRecorded = c.balances(address(this));
        uint midCbal = address(c).balance;
        uint midThisBal = address(this).balance;

        // Now attempt CashOut and detect whether it reverted
        bool coReverted;
        try c.CashOut(withdrawAmount) {
            coReverted = false;
        } catch {
            coReverted = true;
        }

        // Read after-state
        uint afterRecorded = c.balances(address(this));
        uint afterCbal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // Assert general invariant:
        // If CashOut did not revert then:
        // 1) the test contract's recorded balance decreased by exactly withdrawAmount (midRecorded == afterRecorded + withdrawAmount)
        // 2) the test contract's ETH balance increased by exactly withdrawAmount (afterThisBal == midThisBal + withdrawAmount)
        // 3) the contract c's balance decreased by at least withdrawAmount (midCbal >= afterCbal && midCbal - afterCbal >= withdrawAmount)
        // We avoid underflow in the assertion by expressing decreases as equalities/inequalities that don't subtract smaller-from-larger inside assert except where safe.

        assert(
            coReverted
            || (
                (midRecorded == afterRecorded + withdrawAmount)
                && (afterThisBal == midThisBal + withdrawAmount)
                && (midCbal >= afterCbal) && (midCbal - afterCbal >= withdrawAmount)
            )
        );
    }

    // Allow receiving Ether when c sends funds to this test contract
    receive() external payable {}
}

