contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function that exercises Deposit and CashOut with inputs
    function run(uint depositAmt, uint cashAmt) public payable {
        // allow sending Ether for Deposit; ensure this contract has enough Ether
        require(address(this).balance >= depositAmt + 1 wei);

        // initial observed values
        uint beforeContractBal = address(c).balance;
        uint beforeMyBal = c.balances(address(this));

        // perform Deposit if depositAmt > 0 by calling c.Deposit with value depositAmt
        // The Deposit function in C only records if msg.value > MinDeposit (1 ether),
        // so this call may be a no-op. We still call it to set up state.
        if (depositAmt > 0) {
            c.Deposit{value: depositAmt}();
        }

        // read mid-state after Deposit
        uint midContractBal = address(c).balance;
        uint midMyBal = c.balances(address(this));

        // attempt CashOut(cashAmt) and capture whether it reverted
        bool reverted;
        try c.CashOut{value: 0}(cashAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // final observed values
        uint afterContractBal = address(c).balance;
        uint afterMyBal = c.balances(address(this));

        // General invariant to assert:
        // - If CashOut did not revert then midMyBal >= cashAmt and afterMyBal == midMyBal - cashAmt
        //   and afterContractBal == midContractBal - cashAmt.
        // - If CashOut reverted then balances did not decrease (afterMyBal == midMyBal and afterContractBal == midContractBal).
        // This captures that successful CashOut transfers exactly the amount and updates stored balance accordingly.
        assert(
            (!reverted && midMyBal >= cashAmt && afterMyBal == (midMyBal - cashAmt) && afterContractBal == (midContractBal - cashAmt))
            ||
            (reverted && afterMyBal == midMyBal && afterContractBal == midContractBal)
        );
    }

    // allow contract to receive Ether so c can send funds back
    receive() external payable {}
}

