contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test CashOut behavior with an input amount and an initial deposit to ensure some balance.
    function run(uint initialDeposit, uint cashOutAmt) public payable {
        // fund this test contract so it can deposit to c and receive cashouts
        require(address(this).balance >= initialDeposit);

        // read MinDeposit to know whether Deposit will take the branch
        uint minDep = c.MinDeposit();

        // capture before-values
        uint beforeStored = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // If initialDeposit is big enough to trigger Deposit branch, perform a Deposit to ensure sufficient stored balance
        if (initialDeposit > 0) {
            // only send deposit if it's allowed by this contract balance
            c.Deposit{value: initialDeposit}();
        }

        // read after deposit (or unchanged) values
        uint afterDepositStored = c.balances(address(this));
        uint afterDepositContractBal = address(c).balance;

        // Now attempt CashOut(cashOutAmt) and record whether it reverted
        bool reverted;
        try c.CashOut(cashOutAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read final observed values
        uint finalStored = c.balances(address(this));
        uint finalContractBal = address(c).balance;

        // Determine whether CashOut's internal branch condition (_am <= balances[msg.sender]) held according to the observed stored balance prior to the call
        // We use afterDepositStored as the stored balance visible to this test just before CashOut.
        bool shouldAllow = (cashOutAmt <= afterDepositStored);

        // Assert the general rule:
        // - If CashOut reverted, then either the input exceeded stored balance (shouldAllow == false) or the external send failed; we only require that if it reverted and shouldAllow==false then balances and contract balance are unchanged;
        // - If CashOut did not revert and shouldAllow==true then the stored balance decreased by exactly cashOutAmt and the contract balance decreased by at least cashOutAmt (send could forward gas and succeed), otherwise if shouldAllow==false then nothing changed.
        assert(
            // Case: call reverted
            (reverted && (
                // If it reverted while the amount was greater than stored, then no state changes must have occurred
                (!shouldAllow && finalStored == afterDepositStored && finalContractBal == afterDepositContractBal)
                ||
                // Or it reverted despite shouldAllow==true (e.g., send failed or revert in AddMessage); in that case we require only that stored balance reflects the code path: in C the contract subtracts before sending, so if revert happened after subtraction the whole tx reverted and state rolled back — so no state change observable
                (shouldAllow && finalStored == afterDepositStored && finalContractBal == afterDepositContractBal)
            ))
            ||
            // Case: call did not revert
            (!reverted && (
                // Only allowed if amount was <= stored before call, and then stored decreased exactly by cashOutAmt
                (shouldAllow && finalStored + cashOutAmt == afterDepositStored && finalContractBal <= afterDepositContractBal && afterDepositContractBal - finalContractBal >= cashOutAmt)
            ))
        );
    }

    receive() external payable {}
}

