        uint beforeStored = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // If initialDeposit is provided and large enough to satisfy MinDeposit branch, perform Deposit as top-level statement
        if (initialDeposit > 0 && initialDeposit > minDep) {
            c.Deposit{value: initialDeposit}();
        }

        // read stored balance and contract balance after possible deposit
        uint storedBeforeCashOut = c.balances(address(this));
        uint contractBalBeforeCashOut = address(c).balance;

        // attempt CashOut and record whether it reverted (top-level try/catch)
        bool reverted;
