            reverted = false;
        } catch {
            reverted = true;
        }

        // read final observed values
        uint finalStored = c.balances(address(this));
        uint finalContractBal = address(c).balance;

        // Define the predicate that the amount was allowed by stored balance just before CashOut
        bool allowedByStored = (cashOutAmt <= storedBeforeCashOut);

        // Assert the invariant: if CashOut did not revert then it must have been allowedByStored and the stored balance decreased by exactly cashOutAmt.
        // (Other effects on contract balance are not strictly asserted here because external send behavior and Log may affect timing, but stored balance change is deterministic on success.)
        assert((!reverted) == allowedByStored && (
